/* ==================== */
/* ShiftWise CSS Styles */
/* ==================== */

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: #1a1a2e;
  background: #fff;
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  text-decoration: none;
  color: inherit;
}

ul { list-style: none; }

img { max-width: 100%; display: block; }

/* --- Color Variables --- */
:root {
  --primary: #0051C3;
  --primary-dark: #003d9a;
  --accent: #DE5052;
  --accent-hover: #c43e40;
  --dark: #0d1b2a;
  --dark-secondary: #1b263b;
  --gray-100: #f4f6f8;
  --gray-200: #e9ecef;
  --gray-300: #dee2e6;
  --gray-500: #6c757d;
  --gray-600: #495057;
  --white: #ffffff;
  --success: #28a745;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: 'Space Grotesk', 'Inter', sans-serif;
  font-weight: 700;
  line-height: 1.2;
  color: var(--dark);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }

p {
  color: var(--gray-600);
  font-size: 1rem;
  line-height: 1.7;
}

/* --- Utility Classes --- */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 5rem 0;
}

.section-dark {
  background: var(--dark);
  color: var(--white);
}

.section-dark h2,
.section-dark h3,
.section-dark h4 {
  color: var(--white);
}

.section-gray {
  background: var(--gray-100);
}

.text-center { text-align: center; }

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 1.75rem;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.25s ease;
  border: 2px solid transparent;
  text-align: center;
}

.btn-primary {
  background: var(--accent);
  color: var(--white);
  border-color: var(--accent);
}

.btn-primary:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(222, 80, 82, 0.3);
}

.btn-secondary {
  background: transparent;
  color: var(--primary);
  border-color: var(--primary);
}

.btn-secondary:hover {
  background: var(--primary);
  color: var(--white);
  transform: translateY(-2px);
}

.btn-white {
  background: var(--white);
  color: var(--accent);
  border-color: var(--white);
}

.btn-white:hover {
  background: var(--gray-100);
  border-color: var(--gray-100);
  transform: translateY(-2px);
}

.btn-dark {
  background: var(--dark);
  color: var(--white);
  border-color: var(--dark);
}

.btn-dark:hover {
  background: var(--dark-secondary);
  border-color: var(--dark-secondary);
  transform: translateY(-2px);
}

.btn-lg {
  padding: 1rem 2rem;
  font-size: 1.125rem;
}

/* --- Header / Nav --- */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.97);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow 0.3s ease;
}

.header.scrolled {
  box-shadow: 0 2px 20px rgba(0,0,0,0.08);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--dark);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--primary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
  font-size: 1.25rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-links a {
  font-weight: 500;
  color: var(--gray-600);
  transition: color 0.2s;
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--primary);
}

.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--primary);
  transition: width 0.2s;
}

.nav-links a:hover::after,
.nav-links a.active::after {
  width: 100%;
}

.nav-cta {
  margin-left: 1rem;
}

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 8px;
  background: none;
  border: none;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--dark);
  transition: all 0.3s ease;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* --- Mobile Nav --- */
.mobile-nav {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  padding: 1.5rem;
  transform: translateY(-100%);
  opacity: 0;
  transition: all 0.35s ease;
  z-index: 999;
  box-shadow: 0 10px 30px rgba(0,0,0,0.1);
}

.mobile-nav.open {
  transform: translateY(0);
  opacity: 1;
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.mobile-nav-links a {
  padding: 0.75rem 0;
  font-weight: 500;
  color: var(--dark);
  border-bottom: 1px solid var(--gray-200);
}

.mobile-nav-links .btn {
  margin-top: 1rem;
  width: 100%;
}

/* --- Hero Section --- */
.hero {
  padding: 8rem 0 5rem;
  background: linear-gradient(135deg, var(--gray-100) 0%, #e8f0fe 100%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(0,81,195,0.08) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.hero-content {
  position: relative;
  z-index: 1;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--primary);
  color: var(--white);
  padding: 0.375rem 1rem;
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 500;
  margin-bottom: 1.5rem;
}

.hero h1 {
  margin-bottom: 1.5rem;
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--gray-600);
  margin-bottom: 2rem;
  max-width: 500px;
}

.hero-ctas {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.hero-visual {
  position: relative;
  display: flex;
  justify-content: center;
}

.hero-card {
  background: var(--white);
  border-radius: 16px;
  padding: 2rem;
  box-shadow: 0 20px 60px rgba(0,0,0,0.1);
  width: 100%;
  max-width: 480px;
}

.hero-schedule-preview {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}

.schedule-day {
  text-align: center;
}

.schedule-day-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--gray-500);
  margin-bottom: 0.5rem;
}

.schedule-slot {
  height: 40px;
  border-radius: 6px;
  background: var(--gray-200);
  margin-bottom: 0.25rem;
  font-size: 0.625rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-500);
}

.schedule-slot.morning { background: #e3f2fd; color: var(--primary); }
.schedule-slot.afternoon { background: #fff3e0; color: #e65100; }
.schedule-slot.evening { background: #f3e5f5; color: #7b1fa2; }

.hero-stats-row {
  display: flex;
  justify-content: space-between;
  padding-top: 1rem;
  border-top: 1px solid var(--gray-200);
}

.hero-stat {
  text-align: center;
}

.hero-stat-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--dark);
}

.hero-stat-label {
  font-size: 0.75rem;
  color: var(--gray-500);
}

/* --- Features Section --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
  margin-top: 3rem;
}

.feature-card {
  background: var(--white);
  border-radius: 16px;
  padding: 2rem;
  border: 1px solid var(--gray-200);
  transition: all 0.3s ease;
}

.feature-card:hover {
  border-color: var(--primary);
  box-shadow: 0 10px 40px rgba(0,81,195,0.1);
  transform: translateY(-4px);
}

.feature-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--primary), #4080e0);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--white);
  font-size: 1.5rem;
}

.feature-card h3 {
  margin-bottom: 0.75rem;
  font-size: 1.25rem;
}

.feature-card p {
  font-size: 0.9375rem;
}

/* --- How It Works Section --- */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 2rem;
  margin-top: 3rem;
}

.step-card {
  text-align: center;
  padding: 2rem;
}

.step-number {
  width: 64px;
  height: 64px;
  background: var(--primary);
  color: var(--white);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  margin: 0 auto 1.5rem;
}

.step-card h3 {
  margin-bottom: 0.75rem;
}

.step-card p {
  font-size: 0.9375rem;
}

/* --- Testimonials Section --- */
.testimonials-wrapper {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
}

.testimonial-track {
  overflow: hidden;
}

.testimonial-slides {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  flex: 0 0 100%;
  padding: 3rem;
  background: var(--white);
  border-radius: 16px;
  text-align: center;
  box-shadow: 0 10px 40px rgba(0,0,0,0.08);
}

.testimonial-quote {
  font-size: 1.25rem;
  font-style: italic;
  color: var(--dark);
  margin-bottom: 1.5rem;
  line-height: 1.8;
}

.testimonial-author {
  font-weight: 600;
  color: var(--dark);
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--gray-500);
}

.testimonial-nav {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.testimonial-arrow {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--gray-300);
  background: var(--white);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
  font-size: 1.25rem;
  color: var(--gray-600);
}

.testimonial-arrow:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.testimonial-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1.5rem;
}

.testimonial-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  cursor: pointer;
  transition: all 0.2s;
}

.testimonial-dot.active {
  background: var(--primary);
  width: 28px;
  border-radius: 5px;
}

/* --- Stats Section --- */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.stat-item {
  text-align: center;
}

.stat-value {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--accent);
  font-family: 'Space Grotesk', sans-serif;
}

.stat-label {
  font-size: 1rem;
  color: rgba(255,255,255,0.7);
  margin-top: 0.5rem;
}

/* --- Pricing Section (Teaser) --- */
.pricing-teaser {
  background: var(--gray-100);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-top: 3rem;
}

.pricing-card {
  background: var(--white);
  border-radius: 16px;
  padding: 2rem;
  border: 2px solid var(--gray-200);
  text-align: center;
  transition: all 0.3s ease;
}

.pricing-card.featured {
  border-color: var(--primary);
  transform: scale(1.05);
  box-shadow: 0 20px 60px rgba(0,81,195,0.15);
}

.pricing-card h3 {
  margin-bottom: 0.5rem;
}

.pricing-amount {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--dark);
  margin: 1rem 0;
}

.pricing-amount span {
  font-size: 1rem;
  font-weight: 400;
  color: var(--gray-500);
}

.pricing-features {
  margin: 1.5rem 0;
  text-align: left;
}

.pricing-features li {
  padding: 0.5rem 0;
  color: var(--gray-600);
  font-size: 0.9375rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.pricing-features li::before {
  content: '✓';
  color: var(--success);
  font-weight: 700;
}

/* --- CTA Section --- */
.cta-section {
  background: linear-gradient(135deg, var(--primary) 0%, #0a2d5c 100%);
  color: var(--white);
  text-align: center;
  padding: 5rem 0;
}

.cta-section h2 {
  color: var(--white);
  margin-bottom: 1rem;
}

.cta-section p {
  color: rgba(255,255,255,0.85);
  font-size: 1.125rem;
  margin-bottom: 2rem;
}

.cta-section .btn-primary {
  background: var(--accent);
  border-color: var(--accent);
}

/* --- Page Hero (Inner Pages) --- */
.page-hero {
  padding: 8rem 0 4rem;
  background: linear-gradient(135deg, var(--gray-100) 0%, #e8f0fe 100%);
  text-align: center;
}

.page-hero h1 {
  margin-bottom: 1rem;
}

.page-hero p {
  font-size: 1.125rem;
  max-width: 600px;
  margin: 0 auto;
}

/* --- Feature Detail Sections --- */
.feature-detail {
  padding: 4rem 0;
}

.feature-detail-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.feature-detail.reverse .feature-detail-inner {
  direction: rtl;
}

.feature-detail.reverse .feature-detail-content {
  direction: ltr;
}

.feature-detail-content h2 {
  margin-bottom: 1rem;
}

.feature-detail-content p {
  margin-bottom: 1.5rem;
}

.feature-detail-content ul {
  margin-bottom: 1.5rem;
}

.feature-detail-content li {
  padding: 0.5rem 0;
  color: var(--gray-600);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.feature-detail-content li::before {
  content: '✓';
  color: var(--primary);
  font-weight: 700;
}

.feature-detail-visual {
  background: var(--gray-100);
  border-radius: 16px;
  padding: 3rem;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 300px;
}

.mock-schedule {
  width: 100%;
  background: var(--white);
  border-radius: 12px;
  padding: 1.5rem;
  box-shadow: 0 4px 20px rgba(0,0,0,0.08);
}

.mock-schedule-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--gray-200);
}

.mock-schedule-title {
  font-weight: 700;
  color: var(--dark);
}

.mock-schedule-week {
  font-size: 0.875rem;
  color: var(--gray-500);
}

.mock-employee-row {
  display: grid;
  grid-template-columns: 100px repeat(7, 1fr);
  gap: 0.5rem;
  margin-bottom: 0.75rem;
  align-items: center;
}

.mock-employee-name {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--dark);
}

.mock-shift-block {
  height: 36px;
  border-radius: 6px;
  font-size: 0.625rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 500;
}

.mock-shift-block.morning { background: var(--primary); }
.mock-shift-block.afternoon { background: #f57c00; }
.mock-shift-block.evening { background: #7b1fa2; }
.mock-shift-block.off { background: var(--gray-200); color: var(--gray-500); }

/* --- Integrations Grid --- */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
  margin-top: 2rem;
}

.integration-category {
  background: var(--white);
  border-radius: 12px;
  padding: 1.5rem;
  text-align: center;
  border: 1px solid var(--gray-200);
  transition: all 0.3s ease;
}

.integration-category:hover {
  border-color: var(--primary);
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0,81,195,0.1);
}

.integration-icon {
  width: 48px;
  height: 48px;
  background: var(--gray-100);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1rem;
  font-size: 1.25rem;
}

.integration-category h4 {
  margin-bottom: 0.5rem;
}

.integration-category p {
  font-size: 0.875rem;
}

/* --- Pricing Page --- */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin: 2rem 0;
}

.toggle-label {
  font-weight: 500;
  color: var(--gray-600);
}

.toggle-label.active {
  color: var(--dark);
}

.toggle-switch {
  width: 56px;
  height: 30px;
  background: var(--gray-300);
  border-radius: 15px;
  cursor: pointer;
  position: relative;
  transition: background 0.3s;
}

.toggle-switch::after {
  content: '';
  position: absolute;
  width: 24px;
  height: 24px;
  background: var(--white);
  border-radius: 50%;
  top: 3px;
  left: 3px;
  transition: transform 0.3s;
}

.toggle-switch.annual::after {
  transform: translateX(26px);
}

.toggle-switch.annual {
  background: var(--primary);
}

.save-badge {
  background: var(--success);
  color: var(--white);
  padding: 0.25rem 0.75rem;
  border-radius: 50px;
  font-size: 0.75rem;
  font-weight: 600;
}

.pricing-table-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-top: 2rem;
}

.pricing-table-card {
  background: var(--white);
  border-radius: 16px;
  border: 2px solid var(--gray-200);
  overflow: hidden;
  transition: all 0.3s ease;
}

.pricing-table-card:hover {
  border-color: var(--primary);
}

.pricing-table-card.featured {
  border-color: var(--primary);
  box-shadow: 0 20px 60px rgba(0,81,195,0.15);
  transform: scale(1.03);
}

.pricing-table-header {
  padding: 2rem;
  text-align: center;
  border-bottom: 1px solid var(--gray-200);
}

.pricing-table-card.featured .pricing-table-header {
  background: var(--primary);
  color: var(--white);
}

.pricing-table-card.featured .pricing-table-header h3,
.pricing-table-card.featured .pricing-table-header .price {
  color: var(--white);
}

.pricing-table-header h3 {
  margin-bottom: 0.5rem;
}

.price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--dark);
}

.price-period {
  font-size: 1rem;
  font-weight: 400;
  color: var(--gray-500);
}

.pricing-table-body {
  padding: 2rem;
}

.pricing-table-features {
  margin-bottom: 1.5rem;
}

.pricing-table-features li {
  padding: 0.75rem 0;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--gray-600);
  font-size: 0.9375rem;
  border-bottom: 1px solid var(--gray-100);
}

.pricing-table-features li:last-child {
  border-bottom: none;
}

.check-icon {
  color: var(--success);
  font-weight: 700;
  width: 20px;
}

.cross-icon {
  color: var(--gray-400);
  width: 20px;
}

.pricing-table-body .btn {
  width: 100%;
  margin-top: 1rem;
}

/* --- FAQ Accordion --- */
.faq-list {
  max-width: 800px;
  margin: 2rem auto 0;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  padding: 1.5rem 0;
  background: none;
  border: none;
  text-align: left;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--dark);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: color 0.2s;
}

.faq-question:hover {
  color: var(--primary);
}

.faq-icon {
  font-size: 1.5rem;
  transition: transform 0.3s ease;
  color: var(--gray-500);
}

.faq-item.open .faq-icon {
  transform: rotate(45deg);
  color: var(--accent);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 1.5rem;
}

.faq-answer p {
  color: var(--gray-600);
  line-height: 1.7;
}

/* --- About Page --- */
.mission-block {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  margin-top: 3rem;
}

.mission-content h2 {
  margin-bottom: 1.5rem;
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
  margin-top: 3rem;
}

.team-card {
  text-align: center;
  padding: 2rem;
  background: var(--white);
  border-radius: 12px;
  border: 1px solid var(--gray-200);
}

.team-avatar {
  width: 80px;
  height: 80px;
  background: var(--primary);
  border-radius: 50%;
  margin: 0 auto 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 2rem;
  font-weight: 700;
}

.team-card h4 {
  margin-bottom: 0.25rem;
}

.team-card p {
  font-size: 0.875rem;
}

/* --- Contact Page --- */
.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  margin-top: 3rem;
}

.contact-form {
  background: var(--white);
  border-radius: 16px;
  padding: 2.5rem;
  border: 1px solid var(--gray-200);
}

.form-group {
  margin-bottom: 1.5rem;
}

.form-group label {
  display: block;
  font-weight: 500;
  margin-bottom: 0.5rem;
  color: var(--dark);
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 0.875rem 1rem;
  border: 1px solid var(--gray-300);
  border-radius: 8px;
  font-size: 1rem;
  font-family: inherit;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0,81,195,0.1);
}

.form-group textarea {
  resize: vertical;
  min-height: 120px;
}

.form-group input.error,
.form-group select.error,
.form-group textarea.error {
  border-color: var(--accent);
}

.form-error {
  color: var(--accent);
  font-size: 0.875rem;
  margin-top: 0.25rem;
  display: none;
}

.form-group.has-error .form-error {
  display: block;
}

.form-success {
  background: var(--success);
  color: var(--white);
  padding: 1.5rem;
  border-radius: 8px;
  text-align: center;
  display: none;
}

.form-success.show {
  display: block;
}

.form-success h3 {
  color: var(--white);
  margin-bottom: 0.5rem;
}

.office-locations {
  padding: 2rem;
  background: var(--gray-100);
  border-radius: 16px;
}

.office-locations h3 {
  margin-bottom: 1.5rem;
}

.location-item {
  margin-bottom: 1.5rem;
}

.location-item h4 {
  color: var(--primary);
  margin-bottom: 0.25rem;
}

.location-item p {
  font-size: 0.9375rem;
}

.contact-info {
  margin-top: 2rem;
  padding-top: 2rem;
  border-top: 1px solid var(--gray-200);
}

.contact-info-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
  color: var(--gray-600);
}

.contact-info-item strong {
  color: var(--dark);
}

/* --- Footer --- */
.footer {
  background: var(--dark);
  color: var(--white);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand p {
  color: rgba(255,255,255,0.6);
  margin-top: 1rem;
  font-size: 0.9375rem;
}

.footer-col h4 {
  color: var(--white);
  margin-bottom: 1rem;
  font-size: 1rem;
}

.footer-col ul li {
  margin-bottom: 0.75rem;
}

.footer-col ul li a {
  color: rgba(255,255,255,0.6);
  font-size: 0.9375rem;
  transition: color 0.2s;
}

.footer-col ul li a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.1);
  text-align: center;
  color: rgba(255,255,255,0.5);
  font-size: 0.875rem;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-subtitle {
    max-width: 100%;
  }

  .hero-ctas {
    justify-content: center;
  }

  .hero-visual {
    display: none;
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-cards,
  .pricing-table-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .pricing-card.featured {
    transform: none;
  }

  .feature-detail-inner {
    grid-template-columns: 1fr;
  }

  .feature-detail.reverse .feature-detail-inner {
    direction: ltr;
  }

  .contact-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .mobile-nav {
    display: block;
  }

  .section {
    padding: 3rem 0;
  }

  .hero {
    padding: 6rem 0 3rem;
  }

  .integrations-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .stats-grid {
    grid-template-columns: 1fr 1fr;
  }

  .mission-block {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .hero-ctas .btn {
    width: 100%;
  }

  .stats-grid {
    grid-template-columns: 1fr;
  }

  .integrations-grid {
    grid-template-columns: 1fr;
  }

  .pricing-table-card.featured {
    transform: none;
  }
}

/* ==================== */
/* ShiftWise CSS Styles */
/* ==================== */

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: #1a1a2e;
  background: #fff;
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  text-decoration: none;
  color: inherit;
}

ul { list-style: none; }

img { max-width: 100%; display: block; }

/* --- Color Variables --- */
:root {
  --primary: #0051C3;
  --primary-dark: #003d9a;
  --accent: #DE5052;
  --accent-hover: #c43e40;
  --dark: #0d1b2a;
  --dark-secondary: #1b263b;
  --gray-100: #f4f6f8;
  --gray-200: #e9ecef;
  --gray-300: #dee2e6;
  --gray-500: #6c757d;
  --gray-600: #495057;
  --white: #ffffff;
  --success: #28a745;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: 'Space Grotesk', 'Inter', sans-serif;
  font-weight: 700;
  line-height: 1.2;
  color: var(--dark);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }

p {
  color: var(--gray-600);
  font-size: 1rem;
  line-height: 1.7;
}

/* --- Utility Classes --- */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 5rem 0;
}

.section-dark {
  background: var(--dark);
  color: var(--white);
}

.section-dark h2,
.section-dark h3,
.section-dark h4 {
  color: var(--white);
}

.section-gray {
  background: var(--gray-100);
}

.text-center { text-align: center; }

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 1.75rem;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.25s ease;
  border: 2px solid transparent;
  text-align: center;
}

.btn-primary {
  background: var(--accent);
  color: var(--white);
  border-color: var(--accent);
}

.btn-primary:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(222, 80, 82, 0.3);
}

.btn-secondary {
  background: transparent;
  color: var(--primary);
  border-color: var(--primary);
}

.btn-secondary:hover {
  background: var(--primary);
  color: var(--white);
  transform: translateY(-2px);
}

.btn-white {
  background: var(--white);
  color: var(--accent);
  border-color: var(--white);
}

.btn-white:hover {
  background: var(--gray-100);
  border-color: var(--gray-100);
  transform: translateY(-2px);
}

.btn-dark {
  background: var(--dark);
  color: var(--white);
  border-color: var(--dark);
}

.btn-dark:hover {
  background: var(--dark-secondary);
  border-color: var(--dark-secondary);
  transform: translateY(-2px);
}

.btn-lg {
  padding: 1rem 2rem;
  font-size: 1.125rem;
}

/* --- Header / Nav --- */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.97);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow 0.3s ease;
}

.header.scrolled {
  box-shadow: 0 2px 20px rgba(0,0,0,0.08);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--dark);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--primary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
  font-size: 1.25rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-links a {
  font-weight: 500;
  color: var(--gray-600);
  transition: color 0.2s;
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--primary);
}

.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--primary);
  transition: width 0.2s;
}

.nav-links a:hover::after,
.nav-links a.active::after {
  width: 100%;
}

.nav-cta {
  margin-left: 1rem;
}

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 8px;
  background: none;
  border: none;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--dark);
  transition: all 0.3s ease;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* --- Mobile Nav --- */
.mobile-nav {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  padding: 1.5rem;
  transform: translateY(-100%);
  opacity: 0;
  transition: all 0.35s ease;
  z-index: 999;
  box-shadow: 0 10px 30px rgba(0,0,0,0.1);
}

.mobile-nav.open {
  transform: translateY(0);
  opacity: 1;
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.mobile-nav-links a {
  padding: 0.75rem 0;
  font-weight: 500;
  color: var(--dark);
  border-bottom: 1px solid var(--gray-200);
}

.mobile-nav-links .btn {
  margin-top: 1rem;
  width: 100%;
}

/* --- Hero Section --- */
.hero {
  padding: 8rem 0 5rem;
  background: linear-gradient(135deg, var(--gray-100) 0%, #e8f0fe 100%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(0,81,195,0.08) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.hero-content {
  position: relative;
  z-index: 1;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--primary);
  color: var(--white);
  padding: 0.375rem 1rem;
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 500;
  margin-bottom: 1.5rem;
}

.hero h1 {
  margin-bottom: 1.5rem;
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--gray-600);
  margin-bottom: 2rem;
  max-width: 500px;
}

.hero-ctas {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.hero-visual {
  position: relative;
  display: flex;
  justify-content: center;
}

.hero-card {
  background: var(--white);
  border-radius: 16px;
  padding: 2rem;
  box-shadow: 0 20px 60px rgba(0,0,0,0.1);
  width: 100%;
  max-width: 480px;
}

.hero-schedule-preview {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}

.schedule-day {
  text-align: center;
}

.schedule-day-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--gray-500);
  margin-bottom: 0.5rem;
}

.schedule-slot {
  height: 40px;
  border-radius: 6px;
  background: var(--gray-200);
  margin-bottom: 0.25rem;
  font-size: 0.625rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-500);
}

.schedule-slot.morning { background: #e3f2fd; color: var(--primary); }
.schedule-slot.afternoon { background: #fff3e0; color: #e65100; }
.schedule-slot.evening { background: #f3e5f5; color: #7b1fa2; }

.hero-stats-row {
  display: flex;
  justify-content: space-between;
  padding-top: 1rem;
  border-top: 1px solid var(--gray-200);
}

.hero-stat {
  text-align: center;
}

.hero-stat-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--dark);
}

.hero-stat-label {
  font-size: 0.75rem;
  color: var(--gray-500);
}

/* --- Features Section --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
  margin-top: 3rem;
}

.feature-card {
  background: var(--white);
  border-radius: 16px;
  padding: 2rem;
  border: 1px solid var(--gray-200);
  transition: all 0.3s ease;
}

.feature-card:hover {
  border-color: var(--primary);
  box-shadow: 0 10px 40px rgba(0,81,195,0.1);
  transform: translateY(-4px);
}

.feature-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--primary), #4080e0);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--white);
  font-size: 1.5rem;
}

.feature-card h3 {
  margin-bottom: 0.75rem;
  font-size: 1.25rem;
}

.feature-card p {
  font-size: 0.9375rem;
}

/* --- How It Works Section --- */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 2rem;
  margin-top: 3rem;
}

.step-card {
  text-align: center;
  padding: 2rem;
}

.step-number {
  width: 64px;
  height: 64px;
  background: var(--primary);
  color: var(--white);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  margin: 0 auto 1.5rem;
}

.step-card h3 {
  margin-bottom: 0.75rem;
}

.step-card p {
  font-size: 0.9375rem;
}

/* --- Testimonials Section --- */
.testimonials-wrapper {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
}

.testimonial-track {
  overflow: hidden;
}

.testimonial-slides {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  flex: 0 0 100%;
  padding: 3rem;
  background: var(--white);
  border-radius: 16px;
  text-align: center;
  box-shadow: 0 10px 40px rgba(0,0,0,0.08);
}

.testimonial-quote {
  font-size: 1.25rem;
  font-style: italic;
  color: var(--dark);
  margin-bottom: 1.5rem;
  line-height: 1.8;
}

.testimonial-author {
  font-weight: 600;
  color: var(--dark);
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--gray-500);
}

.testimonial-nav {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.testimonial-arrow {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--gray-300);
  background: var(--white);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
  font-size: 1.25rem;
  color: var(--gray-600);
}

.testimonial-arrow:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.testimonial-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1.5rem;
}

.testimonial-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  cursor: pointer;
  transition: all 0.2s;
}

.testimonial-dot.active {
  background: var(--primary);
  width: 28px;
  border-radius: 5px;
}

/* --- Stats Section --- */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.stat-item {
  text-align: center;
}

.stat-value {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--accent);
  font-family: 'Space Grotesk', sans-serif;
}

.stat-label {
  font-size: 1rem;
  color: rgba(255,255,255,0.7);
  margin-top: 0.5rem;
}

/* --- Pricing Section (Teaser) --- */
.pricing-teaser {
  background: var(--gray-100);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-top: 3rem;
}

.pricing-card {
  background: var(--white);
  border-radius: 16px;
  padding: 2rem;
  border: 2px solid var(--gray-200);
  text-align: center;
  transition: all 0.3s ease;
}

.pricing-card.featured {
  border-color: var(--primary);
  transform: scale(1.05);
  box-shadow: 0 20px 60px rgba(0,81,195,0.15);
}

.pricing-card h3 {
  margin-bottom: 0.5rem;
}

.pricing-amount {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--dark);
  margin: 1rem 0;
}

.pricing-amount span {
  font-size: 1rem;
  font-weight: 400;
  color: var(--gray-500);
}

.pricing-features {
  margin: 1.5rem 0;
  text-align: left;
}

.pricing-features li {
  padding: 0.5rem 0;
  color: var(--gray-600);
  font-size: 0.9375rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.pricing-features li::before {
  content: '✓';
  color: var(--success);
  font-weight: 700;
}

/* --- CTA Section --- */
.cta-section {
  background: linear-gradient(135deg, var(--primary) 0%, #0a2d5c 100%);
  color: var(--white);
  text-align: center;
  padding: 5rem 0;
}

.cta-section h2 {
  color: var(--white);
  margin-bottom: 1rem;
}

.cta-section p {
  color: rgba(255,255,255,0.85);
  font-size: 1.125rem;
  margin-bottom: 2rem;
}

.cta-section .btn-primary {
  background: var(--accent);
  border-color: var(--accent);
}

/* --- Page Hero (Inner Pages) --- */
.page-hero {
  padding: 8rem 0 4rem;
  background: linear-gradient(135deg, var(--gray-100) 0%, #e8f0fe 100%);
  text-align: center;
}

.page-hero h1 {
  margin-bottom: 1rem;
}

.page-hero p {
  font-size: 1.125rem;
  max-width: 600px;
  margin: 0 auto;
}

/* --- Feature Detail Sections --- */
.feature-detail {
  padding: 4rem 0;
}

.feature-detail-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.feature-detail.reverse .feature-detail-inner {
  direction: rtl;
}

.feature-detail.reverse .feature-detail-content {
  direction: ltr;
}

.feature-detail-content h2 {
  margin-bottom: 1rem;
}

.feature-detail-content p {
  margin-bottom: 1.5rem;
}

.feature-detail-content ul {
  margin-bottom: 1.5rem;
}

.feature-detail-content li {
  padding: 0.5rem 0;
  color: var(--gray-600);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.feature-detail-content li::before {
  content: '✓';
  color: var(--primary);
  font-weight: 700;
}

.feature-detail-visual {
  background: var(--gray-100);
  border-radius: 16px;
  padding: 3rem;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 300px;
}

.mock-schedule {
  width: 100%;
  background: var(--white);
  border-radius: 12px;
  padding: 1.5rem;
  box-shadow: 0 4px 20px rgba(0,0,0,0.08);
}

.mock-schedule-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--gray-200);
}

.mock-schedule-title {
  font-weight: 700;
  color: var(--dark);
}

.mock-schedule-week {
  font-size: 0.875rem;
  color: var(--gray-500);
}

.mock-employee-row {
  display: grid;
  grid-template-columns: 100px repeat(7, 1fr);
  gap: 0.5rem;
  margin-bottom: 0.75rem;
  align-items: center;
}

.mock-employee-name {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--dark);
}

.mock-shift-block {
  height: 36px;
  border-radius: 6px;
  font-size: 0.625rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 500;
}

.mock-shift-block.morning { background: var(--primary); }
.mock-shift-block.afternoon { background: #f57c00; }
.mock-shift-block.evening { background: #7b1fa2; }
.mock-shift-block.off { background: var(--gray-200); color: var(--gray-500); }

/* --- Integrations Grid --- */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
  margin-top: 2rem;
}

.integration-category {
  background: var(--white);
  border-radius: 12px;
  padding: 1.5rem;
  text-align: center;
  border: 1px solid var(--gray-200);
  transition: all 0.3s ease;
}

.integration-category:hover {
  border-color: var(--primary);
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0,81,195,0.1);
}

.integration-icon {
  width: 48px;
  height: 48px;
  background: var(--gray-100);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1rem;
  font-size: 1.25rem;
}

.integration-category h4 {
  margin-bottom: 0.5rem;
}

.integration-category p {
  font-size: 0.875rem;
}

/* --- Pricing Page --- */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin: 2rem 0;
}

.toggle-label {
  font-weight: 500;
  color: var(--gray-600);
}

.toggle-label.active {
  color: var(--dark);
}

.toggle-switch {
  width: 56px;
  height: 30px;
  background: var(--gray-300);
  border-radius: 15px;
  cursor: pointer;
  position: relative;
  transition: background 0.3s;
}

.toggle-switch::after {
  content: '';
  position: absolute;
  width: 24px;
  height: 24px;
  background: var(--white);
  border-radius: 50%;
  top: 3px;
  left: 3px;
  transition: transform 0.3s;
}

.toggle-switch.annual::after {
  transform: translateX(26px);
}

.toggle-switch.annual {
  background: var(--primary);
}

.save-badge {
  background: var(--success);
  color: var(--white);
  padding: 0.25rem 0.75rem;
  border-radius: 50px;
  font-size: 0.75rem;
  font-weight: 600;
}

.pricing-table-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-top: 2rem;
}

.pricing-table-card {
  background: var(--white);
  border-radius: 16px;
  border: 2px solid var(--gray-200);
  overflow: hidden;
  transition: all 0.3s ease;
}

.pricing-table-card:hover {
  border-color: var(--primary);
}

.pricing-table-card.featured {
  border-color: var(--primary);
  box-shadow: 0 20px 60px rgba(0,81,195,0.15);
  transform: scale(1.03);
}

.pricing-table-header {
  padding: 2rem;
  text-align: center;
  border-bottom: 1px solid var(--gray-200);
}

.pricing-table-card.featured .pricing-table-header {
  background: var(--primary);
  color: var(--white);
}

.pricing-table-card.featured .pricing-table-header h3,
.pricing-table-card.featured .pricing-table-header .price {
  color: var(--white);
}

.pricing-table-header h3 {
  margin-bottom: 0.5rem;
}

.price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--dark);
}

.price-period {
  font-size: 1rem;
  font-weight: 400;
  color: var(--gray-500);
}

.pricing-table-body {
  padding: 2rem;
}

.pricing-table-features {
  margin-bottom: 1.5rem;
}

.pricing-table-features li {
  padding: 0.75rem 0;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--gray-600);
  font-size: 0.9375rem;
  border-bottom: 1px solid var(--gray-100);
}

.pricing-table-features li:last-child {
  border-bottom: none;
}

.check-icon {
  color: var(--success);
  font-weight: 700;
  width: 20px;
}

.cross-icon {
  color: var(--gray-400);
  width: 20px;
}

.pricing-table-body .btn {
  width: 100%;
  margin-top: 1rem;
}

/* --- FAQ Accordion --- */
.faq-list {
  max-width: 800px;
  margin: 2rem auto 0;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  padding: 1.5rem 0;
  background: none;
  border: none;
  text-align: left;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--dark);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: color 0.2s;
}

.faq-question:hover {
  color: var(--primary);
}

.faq-icon {
  font-size: 1.5rem;
  transition: transform 0.3s ease;
  color: var(--gray-500);
}

.faq-item.open .faq-icon {
  transform: rotate(45deg);
  color: var(--accent);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 1.5rem;
}

.faq-answer p {
  color: var(--gray-600);
  line-height: 1.7;
}

/* --- About Page --- */
.mission-block {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  margin-top: 3rem;
}

.mission-content h2 {
  margin-bottom: 1.5rem;
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
  margin-top: 3rem;
}

.team-card {
  text-align: center;
  padding: 2rem;
  background: var(--white);
  border-radius: 12px;
  border: 1px solid var(--gray-200);
}

.team-avatar {
  width: 80px;
  height: 80px;
  background: var(--primary);
  border-radius: 50%;
  margin: 0 auto 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 2rem;
  font-weight: 700;
}

.team-card h4 {
  margin-bottom: 0.25rem;
}

.team-card p {
  font-size: 0.875rem;
}

/* --- Contact Page --- */
.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  margin-top: 3rem;
}

.contact-form {
  background: var(--white);
  border-radius: 16px;
  padding: 2.5rem;
  border: 1px solid var(--gray-200);
}

.form-group {
  margin-bottom: 1.5rem;
}

.form-group label {
  display: block;
  font-weight: 500;
  margin-bottom: 0.5rem;
  color: var(--dark);
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 0.875rem 1rem;
  border: 1px solid var(--gray-300);
  border-radius: 8px;
  font-size: 1rem;
  font-family: inherit;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0,81,195,0.1);
}

.form-group textarea {
  resize: vertical;
  min-height: 120px;
}

.form-group input.error,
.form-group select.error,
.form-group textarea.error {
  border-color: var(--accent);
}

.form-error {
  color: var(--accent);
  font-size: 0.875rem;
  margin-top: 0.25rem;
  display: none;
}

.form-group.has-error .form-error {
  display: block;
}

.form-success {
  background: var(--success);
  color: var(--white);
  padding: 1.5rem;
  border-radius: 8px;
  text-align: center;
  display: none;
}

.form-success.show {
  display: block;
}

.form-success h3 {
  color: var(--white);
  margin-bottom: 0.5rem;
}

.office-locations {
  padding: 2rem;
  background: var(--gray-100);
  border-radius: 16px;
}

.office-locations h3 {
  margin-bottom: 1.5rem;
}

.location-item {
  margin-bottom: 1.5rem;
}

.location-item h4 {
  color: var(--primary);
  margin-bottom: 0.25rem;
}

.location-item p {
  font-size: 0.9375rem;
}

.contact-info {
  margin-top: 2rem;
  padding-top: 2rem;
  border-top: 1px solid var(--gray-200);
}

.contact-info-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
  color: var(--gray-600);
}

.contact-info-item strong {
  color: var(--dark);
}

/* --- Footer --- */
.footer {
  background: var(--dark);
  color: var(--white);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand p {
  color: rgba(255,255,255,0.6);
  margin-top: 1rem;
  font-size: 0.9375rem;
}

.footer-col h4 {
  color: var(--white);
  margin-bottom: 1rem;
  font-size: 1rem;
}

.footer-col ul li {
  margin-bottom: 0.75rem;
}

.footer-col ul li a {
  color: rgba(255,255,255,0.6);
  font-size: 0.9375rem;
  transition: color 0.2s;
}

.footer-col ul li a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.1);
  text-align: center;
  color: rgba(255,255,255,0.5);
  font-size: 0.875rem;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-subtitle {
    max-width: 100%;
  }

  .hero-ctas {
    justify-content: center;
  }

  .hero-visual {
    display: none;
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-cards,
  .pricing-table-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .pricing-card.featured {
    transform: none;
  }

  .feature-detail-inner {
    grid-template-columns: 1fr;
  }

  .feature-detail.reverse .feature-detail-inner {
    direction: ltr;
  }

  .contact-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .mobile-nav {
    display: block;
  }

  .section {
    padding: 3rem 0;
  }

  .hero {
    padding: 6rem 0 3rem;
  }

  .integrations-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .stats-grid {
    grid-template-columns: 1fr 1fr;
  }

  .mission-block {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .hero-ctas .btn {
    width: 100%;
  }

  .stats-grid {
    grid-template-columns: 1fr;
  }

  .integrations-grid {
    grid-template-columns: 1fr;
  }

  .pricing-table-card.featured {
    transform: none;
  }
}

